// Package wire holds the octet codings that the code generated by dmrgen
// for dmr:stream structs calls: the base-128 integers and fractions of
// MOTOTRBO binary XML, and UTF-16 text. It does not allocate except to
// grow a slice of the caller.
package wire

import "math"

// Status is the result of a read.
type Status uint8

// The Status values.
const (
	OK       Status = iota // the value was read
	Short                  // the data ends inside the value
	Overflow               // the value does not fit in 64 bits
)

// Uintvar reads a base-128 integer at data[o]: 7 bits per octet, the most
// significant group first, bit 7 set on every octet but the last. It
// returns the value and the offset after it.
func Uintvar(data []byte, o int) (uint64, int, Status) {
	var v uint64
	for {
		if o >= len(data) {
			return 0, o, Short
		}
		c := data[o]
		o++
		if v>>57 != 0 {
			return 0, o, Overflow
		}
		v = v<<7 | uint64(c&0x7F)
		if c&0x80 == 0 {
			return v, o, OK
		}
	}
}

// Sintvar reads a signed base-128 integer at data[o]: a Uintvar whose
// first octet holds the sign in bit 6 and only 6 bits of the magnitude.
// neg reports the sign bit, so that a negative zero is kept.
func Sintvar(data []byte, o int) (v int64, neg bool, next int, st Status) {
	if o >= len(data) {
		return 0, false, o, Short
	}
	neg = data[o]&0x40 != 0
	first := data[o] &^ 0x40
	var m uint64
	for k := 0; ; k++ {
		if o >= len(data) {
			return 0, false, o, Short
		}
		c := data[o]
		if k == 0 {
			c = first
		}
		o++
		if m>>56 != 0 {
			return 0, false, o, Overflow
		}
		m = m<<7 | uint64(c&0x7F)
		if c&0x80 == 0 {
			break
		}
	}
	if m > math.MaxInt64 {
		return 0, false, o, Overflow
	}
	if neg {
		return -int64(m), true, o, OK
	}
	return int64(m), false, o, OK
}

func fraction(data []byte, o int) (float64, int, Status) {
	start := o
	f, o, st := Uintvar(data, o)
	if st != OK {
		return 0, o, st
	}
	return float64(f) / math.Pow(128, float64(o-start)), o, OK
}

// maxFloatInt is the bound of the integer part of a float number: a
// float64 holds every integer below it exactly.
const maxFloatInt = 1 << 53

// Ufloatvar reads an unsigned number at data[o]: a Uintvar integer part,
// then a Uintvar fraction of n octets over 128 to the power n. An integer
// part of 2^53 or more gives Overflow.
func Ufloatvar(data []byte, o int) (float64, int, Status) {
	i, o, st := Uintvar(data, o)
	if st != OK {
		return 0, o, st
	}
	if i >= maxFloatInt {
		return 0, o, Overflow
	}
	f, o, st := fraction(data, o)
	if st != OK {
		return 0, o, st
	}
	return float64(i) + f, o, OK
}

// Sfloatvar reads a signed number at data[o]: a Sintvar integer part, then
// a Uintvar fraction as in Ufloatvar. The sign applies to both parts. An
// integer part of 2^53 or more in magnitude gives Overflow.
func Sfloatvar(data []byte, o int) (float64, int, Status) {
	i, neg, o, st := Sintvar(data, o)
	if st != OK {
		return 0, o, st
	}
	if i >= maxFloatInt || i <= -maxFloatInt {
		return 0, o, Overflow
	}
	f, o, st := fraction(data, o)
	if st != OK {
		return 0, o, st
	}
	if neg {
		return float64(i) - f, o, OK
	}
	return float64(i) + f, o, OK
}

func groups(v uint64) int {
	n := 1
	for v >>= 7; v != 0; v >>= 7 {
		n++
	}
	return n
}

func appendGroups(dst []byte, v uint64, n int) []byte {
	for k := n - 1; k >= 0; k-- {
		c := byte(v>>(7*k)) & 0x7F
		if k > 0 {
			c |= 0x80
		}
		dst = append(dst, c)
	}
	return dst
}

// UintvarLen returns the number of octets of v as a Uintvar in the fewest
// octets.
func UintvarLen(v uint64) int {
	return groups(v)
}

// PutUintvar writes v as a Uintvar of len(b) octets into b, with leading
// zero groups when b is longer than UintvarLen(v). The caller makes b at
// least that long.
func PutUintvar(b []byte, v uint64) {
	n := len(b)
	for k := range n {
		c := byte(v>>(7*(n-1-k))) & 0x7F
		if k < n-1 {
			c |= 0x80
		}
		b[k] = c
	}
}

// AppendUintvar appends v as a Uintvar in the fewest octets. It allocates
// only to grow dst.
func AppendUintvar(dst []byte, v uint64) []byte {
	return appendGroups(dst, v, groups(v))
}

// AppendSintvar appends v as a Sintvar in the fewest octets. neg sets the
// sign bit of a zero value. It allocates only to grow dst.
func AppendSintvar(dst []byte, v int64, neg bool) []byte {
	m := uint64(v)
	if v < 0 {
		m = uint64(-v)
		neg = true
	}
	n := groups(m)
	if m>>(7*(n-1))&0x40 != 0 {
		n++
	}
	k := len(dst)
	dst = appendGroups(dst, m, n)
	if neg {
		dst[k] |= 0x40
	}
	return dst
}

// FloatvarFits reports whether AppendUfloatvar, or AppendSfloatvar when
// signed, can write v: v is finite, not negative unless signed, and its
// integer part is under 2^53 in magnitude.
func FloatvarFits(v float64, signed bool) bool {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return false
	}
	if v < 0 && !signed {
		return false
	}
	return math.Abs(v) < maxFloatInt
}

func splitFloat(v float64, prec int) (i uint64, f uint64) {
	ip, fp := math.Modf(v)
	scale := math.Pow(128, float64(prec))
	r := math.Round(fp * scale)
	if r >= scale {
		r = scale - 1
	}
	return uint64(ip), uint64(r)
}

// AppendUfloatvar appends v as a Ufloatvar with a fraction of prec octets.
// The caller checks v with FloatvarFits. It allocates only to grow dst.
func AppendUfloatvar(dst []byte, v float64, prec int) []byte {
	i, f := splitFloat(v, prec)
	dst = AppendUintvar(dst, i)
	return appendGroups(dst, f, prec)
}

// AppendSfloatvar appends v as a Sfloatvar with a fraction of prec octets.
// The caller checks v with FloatvarFits. It allocates only to grow dst.
func AppendSfloatvar(dst []byte, v float64, prec int) []byte {
	neg := math.Signbit(v)
	i, f := splitFloat(math.Abs(v), prec)
	dst = AppendSintvar(dst, int64(i), neg)
	return appendGroups(dst, f, prec)
}

// AppendUTF8 appends the UTF-16 text src as UTF-8 to dst. bigEndian picks
// the byte order of src. The text ends at the first NUL code unit; an odd
// last octet is dropped, and a lone surrogate gives U+FFFD. It allocates
// only to grow dst.
func AppendUTF8(dst, src []byte, bigEndian bool) []byte {
	for i := 0; i+1 < len(src); i += 2 {
		r := unit(src, i, bigEndian)
		if r == 0 {
			break
		}
		switch {
		case r >= 0xD800 && r < 0xDC00 && i+3 < len(src):
			lo := unit(src, i+2, bigEndian)
			if lo >= 0xDC00 && lo < 0xE000 {
				r = 0x10000 + (r-0xD800)<<10 + (lo - 0xDC00)
				i += 2
			} else {
				r = 0xFFFD
			}
		case r >= 0xD800 && r < 0xE000:
			r = 0xFFFD
		}
		dst = appendRune(dst, r)
	}
	return dst
}

func unit(src []byte, i int, bigEndian bool) uint32 {
	if bigEndian {
		return uint32(src[i])<<8 | uint32(src[i+1])
	}
	return uint32(src[i+1])<<8 | uint32(src[i])
}

func put(dst []byte, u uint32, bigEndian bool) []byte {
	if bigEndian {
		return append(dst, byte(u>>8), byte(u))
	}
	return append(dst, byte(u), byte(u>>8))
}

// AppendRune appends the code point r to dst as UTF-8. A value over
// U+10FFFF or a surrogate gives U+FFFD. It allocates only to grow dst.
func AppendRune(dst []byte, r rune) []byte {
	if r < 0 || r > 0x10FFFF || (r >= 0xD800 && r < 0xE000) {
		r = 0xFFFD
	}
	return appendRune(dst, uint32(r))
}

func appendRune(dst []byte, r uint32) []byte {
	switch {
	case r < 0x80:
		return append(dst, byte(r))
	case r < 0x800:
		return append(dst, 0xC0|byte(r>>6), 0x80|byte(r)&0x3F)
	case r < 0x10000:
		return append(dst, 0xE0|byte(r>>12), 0x80|byte(r>>6)&0x3F, 0x80|byte(r)&0x3F)
	}
	return append(dst, 0xF0|byte(r>>18), 0x80|byte(r>>12)&0x3F, 0x80|byte(r>>6)&0x3F, 0x80|byte(r)&0x3F)
}

// AppendUTF16 appends the UTF-8 text src as UTF-16 to dst, in big-endian
// or little-endian order. An invalid UTF-8 sequence gives U+FFFD. It
// allocates only to grow dst.
func AppendUTF16(dst, src []byte, bigEndian bool) []byte {
	for i := 0; i < len(src); {
		r, n := decodeRune(src, i)
		i += n
		if r >= 0x10000 {
			r -= 0x10000
			dst = put(dst, 0xD800+r>>10, bigEndian)
			dst = put(dst, 0xDC00+r&0x3FF, bigEndian)
			continue
		}
		dst = put(dst, r, bigEndian)
	}
	return dst
}

func decodeRune(s []byte, i int) (uint32, int) {
	c := s[i]
	var n int
	var r uint32
	var lo uint32
	switch {
	case c < 0x80:
		return uint32(c), 1
	case c&0xE0 == 0xC0:
		n, r, lo = 2, uint32(c&0x1F), 0x80
	case c&0xF0 == 0xE0:
		n, r, lo = 3, uint32(c&0x0F), 0x800
	case c&0xF8 == 0xF0:
		n, r, lo = 4, uint32(c&0x07), 0x10000
	default:
		return 0xFFFD, 1
	}
	if i+n > len(s) {
		return 0xFFFD, 1
	}
	for k := 1; k < n; k++ {
		b := s[i+k]
		if b&0xC0 != 0x80 {
			return 0xFFFD, 1
		}
		r = r<<6 | uint32(b&0x3F)
	}
	if r < lo || r > 0x10FFFF || (r >= 0xD800 && r < 0xE000) {
		return 0xFFFD, 1
	}
	return r, n
}
